import {readFileSync,writeFileSync} from 'node:fs';
import {expect,test} from '@playwright/test';
import {attachPageDiagnostics,attachDiagnostics,openPartie,installRandomSequence,FIRST_SCENARIO_PARTICIPANT_VISIBLE_RANDOM} from './helpers/eloron-ui.mjs';
test.setTimeout(90000);
const ids=['S000011','S000035','S000036','S000053','S000054','S000062'];
async function boot(page,setup={}){
 if(process.env.BATCH15G_BASELINE_HTML)await page.route('**/code/partie-test-1.html?*',route=>route.fulfill({contentType:'text/html',body:readFileSync(process.env.BATCH15G_BASELINE_HTML,'utf8')}));
 await openPartie(page,'raith-yria',{randomValues:FIRST_SCENARIO_PARTICIPANT_VISIBLE_RANDOM});
 await page.waitForFunction(()=>document.querySelector('#btnEndTurn')?.classList.contains('vis')&&!turnTransitionInProgress);
 await page.evaluate(setup=>{
  window.__mythesRandom=()=>0;
  for(const p of [player1,player2]){
   const v=setup[p.key]||{};p.hand=v.hand||[];p.drawPile=v.deck||Array(10).fill('H000005');p.graveyard=v.graveyard||[];p.batch03HandOccurrences=[];p.startingDeckCardIds=[...p.drawPile];
   p.characterId=v.characterId||'mainArgent';p.firstTurnStarted=true;p.resourceState.souls=v.souls??50;p.resourceState.revision++;
   const supplies=qs(playerZoneSelector(p,'appro'));supplies.innerHTML=Array.from({length:6},()=>'<div class="slot-appro" data-player="'+p.key+'"></div>').join('');p.supplies=[];p.botanicalGardenState=createBotanicalGardenState();
   for(const id of v.supplies||['R000020']){const slot=supplies.querySelector('.slot-appro');slot.outerHTML=buildFC(id,p.key);registerSupplyInstance(p,[...supplies.querySelectorAll('.fc')].at(-1));}
   if(!v.supplies){for(const supply of p.supplies){const vector=v.classical?{...createEmptyClassicalResources(),...v.classical}:createCheatCollectorVector(100);supply.currentProduction={...vector};supply.productionState.currentVector={...vector};}}
   recomputeClassicalResources(p);projectSoulState(p);setAvatarHitPoints(p,v.hp??50);
   const zone=qs(playerZoneSelector(p,'servants'));zone.innerHTML=Array.from({length:6},()=>'<div class="slot" data-player="'+p.key+'"></div>').join('');
   for(const [index,entry]of (v.board||[]).entries()){const card=typeof entry==='string'?{id:entry}:entry;zone.querySelector('.slot').outerHTML=buildFC(card.id,p.key);const fc=[...zone.querySelectorAll('.fc')].at(-1);fc.dataset.instance=card.instance||p.key+'-'+index;Object.assign(fc.dataset,card.flags||{});if(card.atk!==undefined||card.hp!==undefined||card.max!==undefined)batch03UpdateStats(fc,{atk:card.atk??Number(fc.dataset.atk),pdv:card.hp??Number(fc.dataset.pdv),pdvMax:card.max??Number(fc.dataset.pdvMax)});delete fc.dataset.new;fc.querySelector('.fc-new-badge')?.remove();}
   for(const zone of ['hand','deck','graveyard'])refreshRuntimeZone(p,zone);
  }
  window.__gPayments=[];const nativePay=applyPaymentPlan;applyPaymentPlan=function(...args){const r=nativePay.apply(this,args);__gPayments.push({cardId:args[2]?.cardId,success:r.success,soulsConsumed:r.soulsConsumed,total:getCanonicalCostDefinition(args[2]?.cardId)?.total});return r;};currentPlayer=player1.key;activePlayer=player1;cardsPlayedThisTurn=0;renderAllHands();document.querySelector('[data-testid="test-resource-panel-collapse"]')?.click();window.__fActions=[];
  const native=playCard;playCard=function(...args){const a={id:args[0],done:false};window.__fActions.push(a);const r=native.apply(this,args);Promise.resolve(r).then(result=>{a.done=true;a.result=result?{success:result.success,reason:result.reason}:null},error=>{a.done=true;a.error=String(error)});return r;};
 },setup);
}
async function cast(page,id){
 await expect(page.locator('.hc[data-id="'+id+'"]').first()).toBeVisible();const before=await page.evaluate(()=>window.__fActions.length);
 await page.evaluate(id=>{const p=playerState(currentPlayer),card=qs(playerZoneSelector(p,'hand')+' .hc[data-id="'+id+'"]'),type=CARDS_DATA[id].type,target=type==='Serviteur'?qs(playerZoneSelector(p,'servants')+' .slot'):type==='Approvisionnement'?(qs(playerZoneSelector(p,'appro')+' .fc[data-botanical-card="'+id+'"]')||qs(playerZoneSelector(p,'appro')+' .slot-appro')):document.querySelector('.board-bg'),dataTransfer=new DataTransfer();if(!card||!target)throw Error('Missing real drag/drop source or destination');for(const [node,type]of [[card,'dragstart'],[target,'dragover'],[target,'drop'],[card,'dragend']])node.dispatchEvent(new DragEvent(type,{bubbles:true,cancelable:true,dataTransfer}));},id);
 await expect.poll(()=>page.evaluate(()=>window.__fActions.length)).toBeGreaterThan(before);
}
async function settled(page){await page.waitForFunction(()=>window.__fActions.at(-1)?.done);expect(await page.evaluate(()=>window.__fActions.at(-1).error)).toBeUndefined();}
async function play(page,id){await cast(page,id);await settled(page);}
async function snapshot(page){return page.evaluate(()=>{const p=player1;return {hand:[...p.hand],deck:playerDrawPile(p).map(getRuntimeCardId),graveyard:p.graveyard.map(getRuntimeCardId),souls:p.resourceState.souls,resources:{...p.resourceState.classical},board:livingServantCardsForPlayer(p).map(fc=>({id:fc.dataset.id,instance:fc.dataset.instance,atk:Number(fc.dataset.atk),hp:Number(fc.dataset.pdv),max:Number(fc.dataset.pdvMax)})),plays:cardsPlayedThisTurn,message:document.querySelector('#notif')?.textContent,error:document.querySelector('#errMsg')?.textContent}})}

async function turn(page){await page.locator('#btnEndTurn').click();await page.waitForFunction(()=>!turnTransitionInProgress);}
async function handOwner(page,key){await page.evaluate(key=>{currentPlayer=key;activePlayer=playerState(key);cardsPlayedThisTurn=0;renderAllHands()},key);}
async function board(page,key='player2'){return page.evaluate(key=>livingServantCardsForPlayer(playerState(key)).map(fc=>({id:fc.dataset.id,instance:fc.dataset.instance,hp:Number(fc.dataset.pdv),max:Number(fc.dataset.pdvMax),gel:Number(fc.dataset.frozen||0),cdg:Number(fc.dataset.frozen_cdg||0),burn:Number(fc.dataset.burning||0),sang:hasSangArdent(fc)})),key);}

test('15G Mur counts Sang-froid within its three real hand summons',async({page})=>{await boot(page,{player1:{hand:['S000011']},player2:{hand:['EDG000001','H000001','H000005','H000006']}});await play(page,'S000011');await handOwner(page,'player2');await play(page,'EDG000001');expect(await page.evaluate(()=>player2.batch05IceWallCharges)).toBe(2);for(const id of ['H000001','H000005'])await play(page,id);expect(await page.evaluate(()=>player2.batch05IceWallCharges)).toBe(0);await turn(page);await turn(page);await play(page,'H000006');expect(await page.evaluate(()=>player2.batch05IceWallCharges)).toBe(0);expect((await board(page)).find(c=>c.id==='H000006').cdg).toBe(0);expect((await board(page)).filter(c=>['H000001','H000005'].includes(c.id)).every(c=>c.cdg===1)).toBe(true);});
