test('15G RED Meteors resolves at both owners end turns and expires after exactly three waves',async({page},testInfo)=>{await boot(page,{player1:{hand:['S000035'],board:[{id:'H000001',hp:100,max:100}]},player2:{board:[{id:'H000005',hp:100,max:100}]}});await play(page,'S000035');await turn(page);expect(await page.evaluate(()=>ongoingEffects.meteores[0]?.remainingWaves)).toBe(2);await turn(page);expect(await page.evaluate(()=>ongoingEffects.meteores[0]?.remainingWaves)).toBe(1);await turn(page);expect(await page.evaluate(()=>ongoingEffects.meteores.length)).toBe(0);const before=await board(page);await page.evaluate(async()=>resolveMeteoresEndOfTurn(activePlayer));expect(await board(page)).toEqual(before);await testInfo.attach('completed-wave-state',{body:Buffer.from(JSON.stringify(await board(page))),contentType:'application/json'});});
test('15G RED Meteors can affect its owners Insensible but preserves the opposing one',async({page})=>{await boot(page,{player1:{hand:['S000035'],board:[{id:'H000036',hp:100,max:100,flags:{insensible:'1'}}]},player2:{board:[{id:'H000036',hp:100,max:100,flags:{insensible:'1'}}]}});await play(page,'S000035');await turn(page);expect((await board(page,'player1'))[0].burn).toBeGreaterThan(0);expect((await board(page))[0].burn).toBe(0);expect((await board(page))[0].hp).toBe(100);});
test('15G RED Chaud-froid applies its initial real Coup de glace without altering its owner',async({page})=>{await boot(page,{player1:{hand:['S000053'],board:['H000001']},player2:{board:[{id:'H000005',hp:40,max:40}]}});const before=await board(page,'player1');await play(page,'S000053');expect((await board(page))[0].cdg).toBe(1);expect(await board(page,'player1')).toEqual(before);expect((await snapshot(page)).graveyard).toContain('S000053');expect((await snapshot(page)).plays).toBe(1);});
test('15G GREEN Boute UI keeps its true present and future dwarf distinction',async({page})=>{await boot(page,{player1:{hand:['S000054','N000013'],board:['N000001','H000001']},player2:{board:['N000001']}});await play(page,'S000054');expect((await board(page,'player1'))[0].sang).toBe(true);expect((await board(page,'player1'))[1].sang).toBe(false);expect((await board(page))[0].sang).toBe(false);await play(page,'N000013');expect((await board(page,'player1')).find(c=>c.id==='N000013').sang).toBe(false);});
test('15G RED Deferlante real choice notification uses French nonbreaking punctuation',async({page})=>{await boot(page,{player1:{hand:['S000062']},player2:{board:[{id:'H000001',hp:40,max:40}]}});await cast(page,'S000062');await page.getByTestId('board-target-choice').first().click();await page.locator('.sort-choice-confirm').click();await settled(page);expect((await board(page))[0].burn).toBe(3);expect((await snapshot(page)).message).not.toMatch(/[^ ][:;!?]/u);});
test('15G RED the six main and expanded card descriptions emphasize every mechanical digit',async({page})=>{await boot(page,{player1:{hand:ids}});const offenders=await page.evaluate(ids=>ids.flatMap(id=>{const holder=document.createElement('div');holder.innerHTML=buildHC(id,player1)+renderZoomDescription({...CARDS_DATA[id],id},facColor('sort'));return [...holder.querySelectorAll('.hc-desc-text,.fz-desc-text')].flatMap(el=>{const walk=document.createTreeWalker(el,NodeFilter.SHOW_TEXT),bad=[];let node;while(node=walk.nextNode())if(/\d/.test(node.textContent)&&!node.parentElement.closest('strong.kv,.card-keyword,.card-named-ability,.canonical-keyword-inline'))bad.push({id,text:node.textContent});return bad})}),ids);expect(offenders).toEqual([]);});

test.beforeEach(async({page})=>{page.__gDiagnostics=attachPageDiagnostics(page)});
test.afterEach(async({page},testInfo)=>{await attachDiagnostics(testInfo,page.__gDiagnostics);if(testInfo.status!==testInfo.expectedStatus)try{await testInfo.attach('15g-model',{body:Buffer.from(JSON.stringify({own:await snapshot(page),opposing:await board(page)},null,2)),contentType:'application/json'})}catch{}expect(page.__gDiagnostics.pageErrors).toEqual([])});

async function observePulses(page){await page.evaluate(()=>{window.__gPulses=[];const seen=new WeakSet(),tick=()=>{for(const fc of document.querySelectorAll('.fc'))for(const a of fc.getAnimations())if(a.animationName==='batch03AbilityPulse'&&!seen.has(a)){seen.add(a);__gPulses.push({id:fc.dataset.id,owner:fc.dataset.player,frames:a.effect.getKeyframes(),duration:a.effect.getTiming().duration});}requestAnimationFrame(tick)};requestAnimationFrame(tick)});}
