test('15G RED selection holds the shared atomic cast lock before payment',async({page})=>{await boot(page,{player1:{hand:['S000062']},player2:{board:[{id:'H000001',hp:40,max:40}]}});const before=await snapshot(page);await cast(page,'S000062');await expect(page.getByTestId('board-target-choice')).toHaveCount(1);expect(await page.evaluate(()=>!!collectionBatch15EState.active)).toBe(true);await expect(page.locator('#btnEndTurn')).toBeDisabled();expect((await snapshot(page)).hand).toEqual(before.hand);expect(await page.locator('.sort-choice-cancel-button').count()).toBe(1);await page.locator('.sort-choice-cancel-button').click();await settled(page);expect(await page.evaluate(()=>collectionBatch15EState.active)).toBeNull();expect((await snapshot(page)).plays).toBe(0);});

