 test('15G payment once and exact zones '+id,async({page})=>{await boot(page,{player1:{hand:[id],board:[{id:'N000001',hp:60,max:60}]},player2:{board:[{id:'H000005',hp:60,max:60}]}});const before=await snapshot(page);await cast(page,id);if(id==='S000062'){await page.getByTestId('board-target-choice').click();await page.getByTestId('board-target-confirm').click()}await settled(page);const after=await snapshot(page),payments=await page.evaluate(()=>__gPayments);expect(payments).toEqual([{cardId:id,success:true,soulsConsumed:before.souls-after.souls,total:cost}]);expect(after.resources).toEqual(before.resources);expect(after.graveyard).toEqual([id]);expect(after.hand).toEqual([]);expect(after.deck).toEqual(before.deck);expect(after.plays).toBe(1);});
