test('15G Chaud-froid advances through hand and effect summons then fresh fire after prior statuses',async({page})=>{await boot(page,{player1:{hand:['S000053']},player2:{hand:['H000001','S000014'],board:[{id:'H000005',hp:60,max:60}]}});await play(page,'S000053');await expect(page.locator('.av-j1 [data-batch03-status-counter="hot-cold"]')).toHaveText('2');await turn(page);expect((await board(page))[0]).toMatchObject({hp:58,cdg:0,burn:0});expect(await page.evaluate(()=>ongoingEffects.chaudFroid[0].phase)).toBe('freeze');await play(page,'H000001');expect((await board(page)).find(c=>c.id==='H000001').gel).toBe(1);await play(page,'S000014');const entries=await board(page);expect(entries.length).toBe(6);expect(entries.slice(1).every(c=>c.gel===1)).toBe(true);await turn(page);expect(await page.evaluate(()=>ongoingEffects.chaudFroid[0].phase)).toBe('fire-pending');const beforeFireGraves=await page.evaluate(()=>player2.graveyard.length);await turn(page);const fired=await board(page);expect(fired.every(c=>c.gel===0)).toBe(true);const deaths=await page.evaluate(n=>player2.graveyard.length-n,beforeFireGraves);expect(fired.filter(c=>c.burn===3).length+deaths).toBe(3);await expect(page.locator('.av-j1 [data-batch03-status-counter="hot-cold"]')).toHaveCount(0);const stable=await board(page);await page.evaluate(()=>resolveBatch15gHotColdStart(player2));expect(await board(page)).toEqual(stable);});

