async function observeG2Frames(page){await page.evaluate(async()=>{const arts=[...document.querySelectorAll('.fc[data-id] img.fi')];await Promise.all(arts.map(i=>i.decode()));if(arts.some(i=>i.naturalWidth===0))throw Error('Visual witness artwork not loaded')});await page.evaluate(()=>{
 window.__g2Frames=[];window.__g2Removed=[];const generation=window.__g2Generation=(window.__g2Generation||0)+1;let frame=0,serial=0,pulse=0;const nodes=new Map(),animations=new WeakMap();
 const read=fc=>({id:fc.dataset.id,instance:fc.dataset.instance,node:nodes.get(fc).serial,hp:Number(fc.querySelector('.fc-pdv-val')?.textContent),modelHp:Number(fc.dataset.pdv),cdg:Number(fc.dataset.frozen_cdg||0),gel:Number(fc.dataset.frozen||0),burn:Number(fc.dataset.burning||0),ice:fc.querySelector('.fc-ice-badge')?.textContent||'',fire:fc.querySelector('.fc-burn-badge')?.textContent||'',connected:fc.isConnected});
 const tick=()=>{if(window.__g2Generation!==generation)return;frame++;for(const fc of document.querySelectorAll('.fc:not([data-type="appro"])'))if(!nodes.has(fc))nodes.set(fc,{serial:++serial,removed:false});for(const[fc,meta]of nodes){if(!fc.isConnected){if(!meta.removed){__g2Removed.push({...read(fc),at:performance.now(),frame});meta.removed=true}continue}for(const a of fc.getAnimations())if(a.animationName==='batch03AbilityPulse'&&Number(a.currentTime)>0){if(!animations.has(a))animations.set(a,++pulse);const r=fc.getBoundingClientRect();__g2Frames.push({...read(fc),at:performance.now(),frame,pulse:animations.get(a),reason:fc.dataset.batch03LastPulseReason,progress:Number(a.currentTime),duration:a.effect.getTiming().duration,keyframes:a.effect.getKeyframes(),visible:r.width>0&&r.height>0,shadow:getComputedStyle(fc).boxShadow});}}requestAnimationFrame(tick)};requestAnimationFrame(tick);
});}
async function firstG2Frame(page,reason,info,label){await page.waitForFunction(reason=>window.__g2Frames?.some(f=>f.reason===reason&&f.visible),reason);await page.screenshot({path:info.outputPath(label+'-first-pulse.png')});}
async function g2Evidence(page,info,label){const data=await page.evaluate(()=>({frames:__g2Frames,removed:__g2Removed}));await info.attach(label+'-rendered-frame-timeline',{body:Buffer.from(JSON.stringify(data,null,2)),contentType:'application/json'});return data;}
function firstG2Pulses(data,reason){const seen=new Set();return data.frames.filter(f=>f.reason===reason&&!seen.has(f.pulse)&&seen.add(f.pulse));}
function assertG2ActualImpact(frames,baseline){expect(frames.length).toBeGreaterThan(0);for(const f of frames){expect(f.visible).toBe(true);expect(f.hp).toBe(f.modelHp);expect(f.keyframes.length).toBeGreaterThan(1);const before=baseline.find(c=>c.instance===f.instance);expect(before,'actual occurrence '+f.instance).toBeTruthy();expect(f.hp<before.hp||f.burn>before.burn,'pulse must start with actual rendered damage/burn on '+f.instance).toBe(true)}}

